exec 2>/dev/null

P=$PWD
/usr/bin/mkfifo "$P/gate"; exec 9<> "$P/gate"
nap() { read -t "${1:-0.05}" -u 9 _junk; }
export BASHSCREEN_STATE_DIR=$P/state SHELL=/does-not-select-the-default-shell
/usr/bin/mkdir -m 700 "$BASHSCREEN_STATE_DIR"
PY=/usr/bin/python3; CH=$P/child.py; LY=$P/layout.py
SESS=()
await() { local i; for ((i=0;i<400;i++)); do [[ -e $1 ]] && return 0; nap 0.02; done; return 1; }
pidgone() { local i; for ((i=0;i<300;i++)); do [[ -d /proc/$1 ]] || return 0; if read -r l < /proc/$1/stat 2>/dev/null; then r=${l##*) }; [[ ${r%% *} == Z ]] && return 0; fi; nap 0.02; done; return 1; }
cleanup() { local s f; for s in "${SESS[@]}"; do screen kill "$s" >/dev/null 2>&1; done; for f in "$P"/*.pid; do [[ -e $f ]] || continue; pidgone "$(<"$f")"; done; }
trap cleanup EXIT
# probe TAG SESSION TARGET: ask the child on TARGET for its TIOCGWINSZ; echoes "rows cols"
probe() { local tag=$1 sess=$2 tgt=$3 n; n=0; [[ -e $P/$tag.sizes ]] && n=$(/usr/bin/wc -l < "$P/$tag.sizes"); screen send-keys "$sess" -p "$tgt" size >/dev/null 2>&1; local i; for ((i=0;i<300;i++)); do [[ -e $P/$tag.sizes && $(/usr/bin/wc -l < "$P/$tag.sizes") -gt $n ]] && break; nap 0.02; done; /usr/bin/tail -n1 "$P/$tag.sizes" 2>/dev/null; }
# geom SESSION WIN PANE: "rows cols" the layout reports for the pane
geom() { screen pane-list "$1" "$2" | while read -r idx r c rows cols rest; do [[ $idx == "$3" ]] && echo "$rows $cols"; done; }
yes_if() { if "$@"; then echo yes; else echo no; fi; }

snap_tree() { /usr/bin/find "$BASHSCREEN_STATE_DIR" -mindepth 1 -printf '%P %y %m\n' 2>/dev/null | /usr/bin/sort; }
snap_procs() { local c l r out=; for c in /proc/[0-9]*; do [[ -r $c/stat ]] || continue; read -r l < "$c/stat" 2>/dev/null || continue; r=${l##*) }; [[ ${r%% *} == Z ]] && continue; out+="${c#/proc/} "; done; echo "$out" | /usr/bin/tr ' ' '\n' | /usr/bin/sort -n | /usr/bin/tr '\n' ' '; }
settle_procs() { local before=$1 i now; for ((i=0;i<100;i++)); do now=$(snap_procs); [[ $now == "$before" ]] && return 0; nap 0.03; done; return 1; }

echo 'not executable' > "$P/plain.txt"; /usr/bin/chmod 644 "$P/plain.txt"; /usr/bin/mkdir "$P/adir"
socks() { /usr/bin/find "$BASHSCREEN_STATE_DIR" -name '*.sock' 2>/dev/null | /usr/bin/sort; }
meta() { /usr/bin/find "$BASHSCREEN_STATE_DIR" -mindepth 1 -printf '%P\n' 2>/dev/null | /usr/bin/grep -v -E 'brokers/|attachers|relay' | /usr/bin/sort; }
b0=$(snap_procs); t0=$(snap_tree); s0=$(socks)
for spec in "missing:/nonexistent/prog" "plainfile:$P/plain.txt" "directory:$P/adir"; do
  label=${spec%%:*}; cmd=${spec#*:}
  screen run -n "f$label" -- "$cmd" arg >/dev/null 2>&1; rc=$?
  settle_procs "$b0"
  echo "run-$label rc-nonzero=$([[ $rc != 0 ]] && echo yes || echo no) tree-unchanged=$([[ $(snap_tree) == "$t0" ]] && echo yes || echo no) procs-unchanged=$([[ $(snap_procs) == "$b0" ]] && echo yes || echo no) sockets-unchanged=$([[ $(socks) == "$s0" ]] && echo yes || echo no)"
done
SESS+=(fl)
screen run -n fl -- "$PY" "$CH" A >/dev/null 2>&1; await "$P/A.ready"
b1=$(snap_procs); m1=$(meta); s1=$(socks); l1=$(screen pane-list fl 0); w1=$(screen win-list fl 2>&1)
for spec in "missing:/nonexistent/prog" "plainfile:$P/plain.txt" "directory:$P/adir"; do
  label=${spec%%:*}; cmd=${spec#*:}
  screen win-create fl "w$label" -- "$cmd" arg >/dev/null 2>&1; rc=$?; settle_procs "$b1"
  echo "win-create-$label rc-nonzero=$([[ $rc != 0 ]] && echo yes || echo no) metadata-unchanged=$([[ $(meta) == "$m1" ]] && echo yes || echo no) windows-unchanged=$([[ $(screen win-list fl 2>&1) == "$w1" ]] && echo yes || echo no) procs-unchanged=$([[ $(snap_procs) == "$b1" ]] && echo yes || echo no) sockets-unchanged=$([[ $(socks) == "$s1" ]] && echo yes || echo no)"
  screen pane-split fl 0 h -- "$cmd" arg >/dev/null 2>&1; rc=$?; settle_procs "$b1"
  echo "pane-split-$label rc-nonzero=$([[ $rc != 0 ]] && echo yes || echo no) metadata-unchanged=$([[ $(meta) == "$m1" ]] && echo yes || echo no) panes-unchanged=$([[ $(screen pane-list fl 0) == "$l1" ]] && echo yes || echo no) procs-unchanged=$([[ $(snap_procs) == "$b1" ]] && echo yes || echo no) sockets-unchanged=$([[ $(socks) == "$s1" ]] && echo yes || echo no)"
done
echo "original-pane-still-alive=$([[ -d /proc/$(<"$P/A.pid") ]] && echo yes || echo no)"

